  ('00000000-0000-4000-8000-0000000035a4', 'erik@prov.se', 'authenticated', 'authenticated'),
  ('00000000-0000-4000-8000-0000000035a5', 'fatima@prov.se', 'authenticated', 'authenticated'),
  ('00000000-0000-4000-8000-0000000035b1', 'b-agare@prov.se', 'authenticated', 'authenticated');

create temp table prov (k text primary key, v uuid) on commit drop;
grant all on prov to authenticated;

set local role authenticated;
set local request.jwt.claims = '{"sub":"00000000-0000-4000-8000-0000000035a1","role":"authenticated","email":"a-agare@prov.se"}';
