insert into employments (org_id, employee_id, form, pay_form, fee_ore, fee_period, decision_reference, starts_on, valid_from, vacation_rule) values
  ((select v from prov where k = 'a'), (select v from prov where k = 'david'), 'uppdrag', 'fee', 2000000, 'year', 'Årsstämma 2026-05-20, § 9', '2026-05-20', '2026-05-20', 'none');

-- Erik: tillsvidare.
insert into employments (org_id, employee_id, form, pay_form, monthly_salary_ore, starts_on, valid_from, vacation_rule) values
  ((select v from prov where k = 'a'), (select v from prov where k = 'erik'), 'tillsvidare', 'monthly', 3200000, '2025-01-01', '2025-01-01', 'sammalon');
insert into prov select 'erik_e', id from employments where employee_id = (select v from prov where k = 'erik');

insert into employee_tax (org_id, employee_id, kind, table_no, column_no, source, valid_from) values
  ((select v from prov where k = 'a'), (select v from prov where k = 'erik'), 'table', 33, 1, 'a-skattsedel', '2026-01-01');
insert into employee_tax (org_id, employee_id, kind, main_employer, source, valid_from) values
  ((select v from prov where k = 'a'), (select v from prov where k = 'david'), 'table', false, 'manual', '2026-01-01');

do $$
declare
  n int;
  r record;
  v_pnr text;
begin
  -- Versionerna: tre för Anna, den förra stängd dagen före den nya.
  select count(*) into n from employments where contract_id = (select v from prov where k = 'anna_c');
  if n <> 3 then raise exception 'Anna har % versioner, väntade 3.', n; end if;
  select count(*) into n from employments where contract_id = (select v from prov where k = 'anna_c') and valid_to is null;
  if n <> 1 then raise exception 'Anna har % öppna versioner.', n; end if;
  select valid_to into r from employments where contract_id = (select v from prov where k = 'anna_c') and version = 1;
  if r.valid_to <> '2026-02-28' then raise exception 'Version 1 stängdes %.', r.valid_to; end if;

  -- En version kan inte gälla före den förra, och ingen rad ändras eller tas bort.
  begin
    insert into employments (org_id, employee_id, contract_id, form, pay_form, monthly_salary_ore, starts_on, valid_from, vacation_rule)
    values ((select v from prov where k = 'a'), (select v from prov where k = 'anna'), (select v from prov where k = 'anna_c'), 'tillsvidare', 'monthly', 1, '2026-01-15', '2026-02-01', 'sammalon');
    raise exception 'En version före den gällande gick in';
  exception when invalid_parameter_value then null;
  end;
  begin
    update employments set monthly_salary_ore = 1 where id = (select v from prov where k = 'erik_e');
    raise exception 'A1 kunde ändra en anställning';
  exception when insufficient_privilege or feature_not_supported then null;
  end;
  begin
    delete from employments where id = (select v from prov where k = 'erik_e');
    raise exception 'A1 kunde ta bort en anställning';
  exception when insufficient_privilege or feature_not_supported then null;
  end;
  -- Skatt: ingen procentsort, ingen huvudarbetsgivare utan tabell.
  begin
    insert into employee_tax (org_id, employee_id, kind, source, valid_from) values ((select v from prov where k = 'a'), (select v from prov where k = 'anna'), 'percent', 'manual', '2026-01-01');
    raise exception 'Skattesorten percent gick in';
  exception when check_violation then null;
  end;
  begin
    insert into employee_tax (org_id, employee_id, kind, main_employer, source, valid_from) values ((select v from prov where k = 'a'), (select v from prov where k = 'anna'), 'table', true, 'manual', '2026-01-01');
    raise exception 'Huvudarbetsgivare utan tabell gick in';
  exception when check_violation then null;
  end;
  -- Styrelseuppdrag har arvode och ingen semester; vikariat säger vem.
  begin
    insert into employments (org_id, employee_id, form, pay_form, fee_ore, fee_period, starts_on, valid_from, vacation_rule)
    values ((select v from prov where k = 'a'), (select v from prov where k = 'david'), 'uppdrag', 'fee', 1, 'year', '2026-01-01', '2026-01-01', 'procent');
    raise exception 'Uppdrag med semester gick in';
  exception when check_violation then null;
  end;
  begin
    insert into employments (org_id, employee_id, form, pay_form, hourly_rate_ore, starts_on, valid_from, vacation_rule, vacation_percent)
    values ((select v from prov where k = 'a'), (select v from prov where k = 'bertil'), 'vikariat', 'hourly', 1, '2026-01-01', '2026-01-01', 'procent', 12);
    raise exception 'Vikariat utan ersatt person gick in';
  exception when check_violation then null;
  end;

  -- Kryptering: personnumret maskerat, födelsedagen i klartext, kryptotexten går inte att välja.
  select pnr_masked, birth_date, bank_account_masked, bank_clearing into r from employees where id = (select v from prov where k = 'anna');
  if r.pnr_masked <> '19850412-XXXX' or r.birth_date <> '1985-04-12' then raise exception 'Annas maskerade uppgifter: % %', r.pnr_masked, r.birth_date; end if;
  if r.bank_account_masked <> '••••6789' or r.bank_clearing <> '8327' then raise exception 'Annas konto: % %', r.bank_clearing, r.bank_account_masked; end if;
  begin
    perform pnr_enc from employees limit 1;
    raise exception 'pnr_enc gick att välja';
  exception when insufficient_privilege then null;
  end;
  begin
    perform pnr_hash from employees limit 1;
    raise exception 'pnr_hash gick att välja';
  exception when insufficient_privilege then null;
  end;
  -- Samma personnummer två gånger stoppas, utan att något dekrypteras.
  begin
    perform hr_create_employee((select v from prov where k = 'a'), '{"name":"Dubblett"}', '198504121232');
    raise exception 'Samma personnummer gick in två gånger';
  exception when unique_violation then null;
  end;
  -- Ägaren ser personnumret, och det loggas.
  v_pnr := hr_employee_pnr((select v from prov where k = 'anna'), 'prov');
  if v_pnr <> '198504121232' then raise exception 'Fel personnummer: %', v_pnr; end if;
  if hr_employee_bank_account((select v from prov where k = 'anna')) <> '9123456789' then raise exception 'Fel kontonummer'; end if;
  select count(*) into n from events where aggregate_id = (select v from prov where k = 'anna') and type in ('employee.pnr_revealed', 'employee.bank_revealed');
  if n <> 2 then raise exception 'Visningarna loggades inte (%).', n; end if;
  select count(*) into n from events where aggregate_id = (select v from prov where k = 'anna') and type in ('employee.created', 'employment.created', 'employment.versioned');
  if n <> 4 then raise exception 'Väntade 4 händelser för Anna (ny, avtal, två versioner), fick %.', n; end if;

  -- Klockorna i databasen, från versionerna.
  select * into r from employment_clocks((select v from prov where k = 'a'), '2026-10-30') where employee_id = (select v from prov where k = 'bertil');
  if r.vikariat_days <> 731 or not r.vikariat_converted or r.sava_days <> 30 then
    raise exception 'Bertils klockor: vikariat % (%), SÄVA %', r.vikariat_days, r.vikariat_converted, r.sava_days;
  end if;
  select * into r from employment_clocks((select v from prov where k = 'a'), '2026-10-30') where employee_id = (select v from prov where k = 'cecilia');
  if r.sava_days <> 79 then raise exception 'Cecilias SÄVA-dagar: %, väntade 19 + 60.', r.sava_days; end if;
  select * into r from employment_clocks((select v from prov where k = 'a'), '2026-06-01') where employee_id = (select v from prov where k = 'anna');
  if r.probation_starts_on <> '2026-01-15' or r.probation_ends_on <> '2026-07-14' or r.probation_notice_by <> '2026-06-30' or r.probation_days_left <> 43 then
    raise exception 'Annas provanställning: % till %, besked %, % dagar', r.probation_starts_on, r.probation_ends_on, r.probation_notice_by, r.probation_days_left;
  end if;
  select * into r from employment_clocks((select v from prov where k = 'a'), '2026-10-30') where employee_id = (select v from prov where k = 'david');
  if r.sava_days <> 0 or r.vikariat_days <> 0 or r.probation_ends_on is not null then raise exception 'David har klockor'; end if;
  select count(*) into n from employment_clocks((select v from prov where k = 'a'), '2026-10-30');
  if n <> 6 then raise exception 'employment_clocks gav % rader, väntade 6.', n; end if;
end $$;

-- Ett avtal: PDF:en i bucketen hr, raden, signeringen.
insert into storage.objects (bucket_id, name) values
  ('hr', (select v from prov where k = 'a') || '/' || (select v from prov where k = 'erik') || '/avtal-erik.pdf'),
  ('hr', (select v from prov where k = 'a') || '/' || (select v from prov where k = 'anna') || '/avtal-anna.pdf');
insert into employment_documents (org_id, employee_id, employment_id, title, template, template_version, storage_path, sha256, size_bytes)
values ((select v from prov where k = 'a'), (select v from prov where k = 'erik'), (select v from prov where k = 'erik_e'), 'Anställningsavtal', 'contract-tillsvidare', '2026-10-30',
        (select v from prov where k = 'a') || '/' || (select v from prov where k = 'erik') || '/avtal-erik.pdf', repeat('a', 64), 1000);
insert into prov select 'erik_doc', id from employment_documents where employee_id = (select v from prov where k = 'erik');
insert into employment_documents (org_id, employee_id, employment_id, title, template, template_version, storage_path, sha256, size_bytes)
select (select v from prov where k = 'a'), (select v from prov where k = 'anna'), id, 'Anställningsavtal', 'contract-provanstallning', '2026-10-30',
       (select v from prov where k = 'a') || '/' || (select v from prov where k = 'anna') || '/avtal-anna.pdf', repeat('b', 64), 1000
  from employments where contract_id = (select v from prov where k = 'anna_c') and version = 1;

do $$
declare
  n int;
begin
  -- Fel organisation i sökvägen går inte att skriva.
  begin
    insert into storage.objects (bucket_id, name) values ('hr', (select v from prov where k = 'b') || '/' || (select v from prov where k = 'erik') || '/x.pdf');
    raise exception 'A1 kunde lägga en fil under B';
  exception when insufficient_privilege then null;
  end;
  perform hr_sign_document((select v from prov where k = 'erik_doc'), current_date);
  if (select document_id from employments where id = (select v from prov where k = 'erik_e')) <> (select v from prov where k = 'erik_doc') then
    raise exception 'Versionen fick inte det signerade avtalet';
  end if;
  begin
    perform hr_sign_document((select v from prov where k = 'erik_doc'), current_date);
    raise exception 'Avtalet kunde signeras två gånger';
  exception when feature_not_supported then null;
  end;
  begin
    update employment_documents set title = 'Ändrad' where id = (select v from prov where k = 'erik_doc');
    raise exception 'Avtalet kunde ändras';
  exception when insufficient_privilege or feature_not_supported then null;
  end;
  select count(*) into n from events where aggregate_id = (select v from prov where k = 'erik') and type in ('employment_document.created', 'employment_document.signed');
  if n <> 2 then raise exception 'Avtalets händelser saknas (%).', n; end if;
end $$;

-- ---------------------------------------------------------------- rättelserna i 0036

