  ((select v from prov where k = 'a'), (select v from prov where k = 'gunnar'), 'sava', 'hourly', 17500, '2026-06-01', '2026-06-30', '2026-06-01', 'procent', 12);
insert into prov select 'gunnar_c', contract_id from employments where employee_id = (select v from prov where k = 'gunnar');
insert into employments (org_id, employee_id, contract_id, form, pay_form, hourly_rate_ore, starts_on, ends_on, valid_from, vacation_rule, vacation_percent, change_reason) values
  ((select v from prov where k = 'a'), (select v from prov where k = 'gunnar'), (select v from prov where k = 'gunnar_c'), 'sava', 'hourly', 17500, '2026-06-01', '2026-08-31', '2026-07-10', 'procent', 12, 'Förlängd i efterhand');

-- Skatt: samma datum två gånger, den senare rättar den förra.
insert into employee_tax (org_id, employee_id, kind, table_no, column_no, source, valid_from, created_at) values
  ((select v from prov where k = 'a'), (select v from prov where k = 'erik'), 'table', 33, 1, 'manual', '2026-11-01', now() - interval '1 hour'),
  ((select v from prov where k = 'a'), (select v from prov where k = 'erik'), 'table', 34, 1, 'a-skattsedel', '2026-11-01', now());

do $$
declare
  n int;
  r record;
begin
  select * into r from employment_clocks((select v from prov where k = 'a'), '2026-10-30', (select v from prov where k = 'gunnar'));
  if r.sava_days <> 82 then raise exception 'Gunnars SÄVA-dagar: %, väntade 82 (luckan räknades).', r.sava_days; end if;
  select count(*) into n from employment_clocks((select v from prov where k = 'a'), '2026-10-30', (select v from prov where k = 'gunnar'));
  if n <> 1 then raise exception 'Klockan för en person gav % rader.', n; end if;
  -- Den senast inlagda raden för ett datum gäller.
  select table_no into r from employee_tax where employee_id = (select v from prov where k = 'erik') and valid_from <= '2026-11-15'
   order by valid_from desc, created_at desc limit 1;
  if r.table_no <> 34 then raise exception 'Rättelsen av skattetabellen gäller inte (%).', r.table_no; end if;
  -- Ett pappersavtal kan markeras signerat på anställningens startdag, inte före och inte i framtiden.
  begin
    perform hr_sign_document((select id from employment_documents where employee_id = (select v from prov where k = 'anna')), '2026-01-14');
    raise exception 'Signering före anställningens start gick igenom';
  exception when invalid_parameter_value then null;
  end;
  begin
    perform hr_sign_document((select id from employment_documents where employee_id = (select v from prov where k = 'anna')), current_date + 5);
    raise exception 'Signering i framtiden gick igenom';
  exception when invalid_parameter_value then null;
  end;
  perform hr_sign_document((select id from employment_documents where employee_id = (select v from prov where k = 'anna')), '2026-01-15');
  if (select signed_at from employment_documents where employee_id = (select v from prov where k = 'anna')) <> '2026-01-15' then
    raise exception 'Annas pappersavtal kunde inte markeras signerat på startdagen';
  end if;
end $$;

-- ---------------------------------------------------------------- B ser inget av A

set local request.jwt.claims = '{"sub":"00000000-0000-4000-8000-0000000035b1","role":"authenticated","email":"b-agare@prov.se"}';
do $$
declare n int;
begin
  select count(*) into n from employees where org_id = (select v from prov where k = 'a');
  if n <> 0 then raise exception 'B ser A:s personal'; end if;
  select count(*) into n from employments;
  if n <> 0 then raise exception 'B ser A:s anställningar'; end if;
  select count(*) into n from employment_documents;
  if n <> 0 then raise exception 'B ser A:s avtal'; end if;
  select count(*) into n from storage.objects where bucket_id = 'hr';
  if n <> 0 then raise exception 'B ser A:s avtalsfiler'; end if;
  select count(*) into n from events where aggregate_type = 'employee';
  if n <> 0 then raise exception 'B ser A:s personalhändelser'; end if;
  select count(*) into n from employment_clocks((select v from prov where k = 'a'), '2026-10-30');
  if n <> 0 then raise exception 'B får A:s klockor'; end if;
  begin
    insert into employments (org_id, employee_id, form, pay_form, monthly_salary_ore, starts_on, valid_from, vacation_rule)
    values ((select v from prov where k = 'a'), (select v from prov where k = 'erik'), 'tillsvidare', 'monthly', 1, '2026-01-01', '2026-01-01', 'sammalon');
    raise exception 'B kunde skapa en anställning i A';
  exception when insufficient_privilege then null;
  end;
  begin
    perform hr_create_employee((select v from prov where k = 'a'), '{"name":"Intrång"}', null);
    raise exception 'B kunde lägga till personal i A';
  exception when insufficient_privilege then null;
  end;
  begin
    perform hr_employee_pnr((select v from prov where k = 'anna'));
    raise exception 'B fick Annas personnummer';
  exception when insufficient_privilege then null;
  end;
end $$;

-- ---------------------------------------------------------------- konsulten läser, skriver inte

set local request.jwt.claims = '{"sub":"00000000-0000-4000-8000-0000000035a2","role":"authenticated","email":"a-konsult@prov.se"}';
do $$
declare n int;
begin
  select count(*) into n from employees where org_id = (select v from prov where k = 'a');
  if n <> 7 then raise exception 'Konsulten ser % personer, väntade 7.', n; end if;
  select count(*) into n from employment_documents;
  if n <> 2 then raise exception 'Konsulten ser % avtal.', n; end if;
  select count(*) into n from storage.objects where bucket_id = 'hr';
  if n <> 2 then raise exception 'Konsulten ser % avtalsfiler.', n; end if;
  select count(*) into n from events where aggregate_type = 'employee';
  if n = 0 then raise exception 'Konsulten ser inte personalhändelserna'; end if;
  select count(*) into n from employment_clocks((select v from prov where k = 'a'), '2026-10-30');
  if n <> 7 then raise exception 'Konsulten får % klockor.', n; end if;
  begin
    insert into employments (org_id, employee_id, form, pay_form, monthly_salary_ore, starts_on, valid_from, vacation_rule)
    values ((select v from prov where k = 'a'), (select v from prov where k = 'erik'), 'tillsvidare', 'monthly', 1, '2026-01-01', '2026-01-01', 'sammalon');
    raise exception 'Konsulten kunde skapa en anställning';
  exception when insufficient_privilege then null;
  end;
  begin
    insert into employee_tax (org_id, employee_id, kind, table_no, column_no, source, valid_from)
    values ((select v from prov where k = 'a'), (select v from prov where k = 'erik'), 'table', 33, 1, 'manual', '2026-06-01');
    raise exception 'Konsulten kunde lägga in skatt';
  exception when insufficient_privilege then null;
  end;
  begin
    perform hr_create_employee((select v from prov where k = 'a'), '{"name":"Från konsulten"}', null);
    raise exception 'Konsulten kunde lägga till personal';
  exception when insufficient_privilege then null;
  end;
  begin
    perform hr_employee_pnr((select v from prov where k = 'anna'));
    raise exception 'Konsulten fick Annas personnummer';
  exception when insufficient_privilege then null;
  end;
  begin
    perform hr_sign_document((select v from prov where k = 'erik_doc'), current_date);
    raise exception 'Konsulten kunde signera';
  exception when insufficient_privilege then null;
  end;
  update employees set name = 'Ändrad av konsulten' where id = (select v from prov where k = 'erik');
  if (select name from employees where id = (select v from prov where k = 'erik')) <> 'Erik Eriksson' then
    raise exception 'Konsulten kunde ändra en person';
  end if;
end $$;

-- ---------------------------------------------------------------- personal (staff) ser ingen personal

set local request.jwt.claims = '{"sub":"00000000-0000-4000-8000-0000000035a3","role":"authenticated","email":"a-personal@prov.se"}';
do $$
declare n int;
begin
  select count(*) into n from employees;
  if n <> 0 then raise exception 'Staff ser personalregistret'; end if;
  select count(*) into n from employee_tax;
  if n <> 0 then raise exception 'Staff ser skatteuppgifter'; end if;
  select count(*) into n from events where aggregate_type = 'employee';
  if n <> 0 then raise exception 'Staff ser personalhändelser'; end if;
  select count(*) into n from customers where org_id = (select v from prov where k = 'a');
  if n <> 1 then raise exception 'Staff ser inte kunderna längre (%).', n; end if;
  begin
    perform hr_employee_pnr((select v from prov where k = 'anna'));
    raise exception 'Staff fick Annas personnummer';
  exception when insufficient_privilege then null;
  end;
end $$;

-- ---------------------------------------------------------------- den anställde ser bara sig själv

-- Erik bjuds in som employee och kopplas till sin rad via e-postadressen.
reset role;
insert into memberships (org_id, user_id, role) values
  ((select v from prov where k = 'a'), '00000000-0000-4000-8000-0000000035a4', 'employee'),
  ((select v from prov where k = 'a'), '00000000-0000-4000-8000-0000000035a5', 'employee');
do $$
begin
  if (select user_id from employees where id = (select v from prov where k = 'erik')) is distinct from '00000000-0000-4000-8000-0000000035a4' then
    raise exception 'Erik kopplades inte till sin inloggning';
  end if;
end $$;

set local role authenticated;
set local request.jwt.claims = '{"sub":"00000000-0000-4000-8000-0000000035a4","role":"authenticated","email":"erik@prov.se"}';
do $$
declare n int;
begin
  select count(*) into n from employees;
  if n <> 1 or (select id from employees) <> (select v from prov where k = 'erik') then raise exception 'Erik ser % personer.', n; end if;
  select count(*) into n from employments;
  if n <> 1 then raise exception 'Erik ser % anställningar.', n; end if;
  select count(*) into n from employment_documents;
  if n <> 1 then raise exception 'Erik ser % avtal.', n; end if;
  select count(*) into n from storage.objects where bucket_id = 'hr';
  if n <> 1 then raise exception 'Erik ser % avtalsfiler.', n; end if;
  select count(*) into n from employee_tax;
  if n <> 3 then raise exception 'Erik ser % skatterader.', n; end if;
  select count(*) into n from employment_clocks((select v from prov where k = 'a'), '2026-10-30');
  if n <> 1 then raise exception 'Erik får % klockor.', n; end if;
  -- Resten av organisationen är stängd: kunder, loggboken, fakturor.
  select count(*) into n from customers;
  if n <> 0 then raise exception 'Erik ser kunder'; end if;
  select count(*) into n from events;
  if n <> 0 then raise exception 'Erik ser loggboken'; end if;
  select count(*) into n from invoices;
  if n <> 0 then raise exception 'Erik ser fakturor'; end if;
  select count(*) into n from memberships;
  if n <> 1 then raise exception 'Erik ser % medlemsrader.', n; end if;
  select count(*) into n from organizations;
  if n <> 1 then raise exception 'Erik ser inte sin organisation (%).', n; end if;
  begin
    perform hr_employee_pnr((select v from prov where k = 'erik'));
    raise exception 'Erik fick personnumret i klartext';
  exception when insufficient_privilege then null;
  end;
  begin
    insert into employments (org_id, employee_id, form, pay_form, monthly_salary_ore, starts_on, valid_from, vacation_rule)
    values ((select v from prov where k = 'a'), (select v from prov where k = 'erik'), 'tillsvidare', 'monthly', 99900000, '2026-01-01', '2026-01-01', 'sammalon');
    raise exception 'Erik kunde skriva sin egen anställning';
  exception when insufficient_privilege then null;
  end;
  update employees set name = 'Erik själv' where id = (select v from prov where k = 'erik');
  if (select name from employees where id = (select v from prov where k = 'erik')) <> 'Erik Eriksson' then
    raise exception 'Erik kunde ändra sin rad';
  end if;
end $$;

-- Fatima kopplades också via e-posten men har ingen anställning än: hon ser
-- sin egen rad och inget annat.
set local request.jwt.claims = '{"sub":"00000000-0000-4000-8000-0000000035a5","role":"authenticated","email":"fatima@prov.se"}';
do $$
declare n int;
begin
  select count(*) into n from employees;
  if n <> 1 or (select id from employees) <> (select v from prov where k = 'fatima') then raise exception 'Fatima ser % personer, väntade sin egen.', n; end if;
  select count(*) into n from employments;
  if n <> 0 then raise exception 'Fatima ser % anställningar.', n; end if;
end $$;

-- ---------------------------------------------------------------- LAS-klockornas testfall

reset role;
create function pg_temp.prov_clock(p_name text, p_periods las_period[], p_as_of date, p_expected jsonb) returns void
  language plpgsql
as $$
declare
  v_actual jsonb;
  k text;
begin
  select to_jsonb(c) into v_actual from las_clocks(p_periods, p_as_of) c;
  for k in select jsonb_object_keys(p_expected) loop
    if v_actual->k is distinct from p_expected->k then
      raise exception 'Klocka "%": % är %, referensen säger %.', p_name, k, v_actual->k, p_expected->k;
    end if;
  end loop;
end;
$$;

